"""Build the vendored libvpx v1.15.2 (BSD-3, startup/third_party/libvpx) as a VP9-decoder-only native static archive,
plus the movie decode shim (startup/host_movie_vpx.c) that host_movie.h references weakly.

No configure/make: like build_opus.py the sources are compiled directly with the runtime's zig toolchain and target
(x86_64-windows-gnu). Configuration (written to vpx-build/config/):
  vpx_config.h      every VPX_ARCH_/HAVE_/CONFIG_ name configure would emit (lists parsed from libvpx/configure),
                    with x86_64, SSE..AVX2 intrinsics, runtime CPU detection, multithreading (Win32 threads) and the
                    VP9 decoder enabled; no encoders, VP8, high bit depth, postproc, examples, tools or tests.
  *_rtcd.h          generated by libvpx's own build/make/rtcd.pl (perl) with --disable-mmx --disable-avx512, then
                    filtered: libvpx's .asm (nasm/yasm) files are not built, so every dispatch to a SIMD variant
                    that no compiled intrinsics file defines falls back to the C version. The defined set is read
                    from the COFF symbol tables of the intrinsics objects (first pass).
  vpx_version.h     from CHANGELOG (v1.15.2).
Output: startup/third_party/vpx-build/libvpx.a and libtotk_movie_vpx.a (rebuilt only when sources/flags change).
Run directly it lowers its own priority; compiles always run below normal priority with at most JOBS parallel compiles (the game may be running).
link_args() for the runtime DLL: the shim whole-archive (weak references do not extract archive members), then libvpx.
"""
import concurrent.futures,ctypes,hashlib,json,os,re,struct,subprocess,sys
from pathlib import Path

HERE=Path(__file__).resolve().parent
TP=HERE      # startup/third_party
STARTUP=TP.parent
SRC=TP/'libvpx'
OUT=TP/'vpx-build'
CONFIG=OUT/'config'
ZIG=STARTUP.parent/'tools/zig-x86_64-windows-0.16.0/zig.exe'
PERL=os.environ.get('PERL','perl')
SHIM=STARTUP/'host_movie_vpx.c'
JOBS=int(os.environ.get('TOTK_LIB_JOBS','2'))
BELOW_NORMAL=0x4000
FLAGS=['-target','x86_64-windows-gnu','-std=gnu99','-O2','-w','-DNDEBUG','-D_WIN32_WINNT=0x0601','-fno-sanitize=undefined']

ENABLED={'VPX_ARCH_X86_64','HAVE_SSE','HAVE_SSE2','HAVE_SSE3','HAVE_SSSE3','HAVE_SSE4_1','HAVE_AVX','HAVE_AVX2','HAVE_VPX_PORTS',
         'CONFIG_GCC','CONFIG_RUNTIME_CPU_DETECT','CONFIG_MULTITHREAD','CONFIG_VP9','CONFIG_VP9_DECODER','CONFIG_DECODERS',
         'CONFIG_OS_SUPPORT','CONFIG_STATIC','CONFIG_INSTALL_LIBS'}
C_SOURCES='''
vpx/src/vpx_decoder.c vpx/src/vpx_codec.c vpx/src/vpx_image.c
vpx_mem/vpx_mem.c
vpx_scale/generic/yv12config.c vpx_scale/generic/yv12extend.c vpx_scale/vpx_scale_rtcd.c
vpx_util/vpx_thread.c
vpx_dsp/prob.c vpx_dsp/bitreader.c vpx_dsp/bitreader_buffer.c vpx_dsp/intrapred.c vpx_dsp/vpx_convolve.c
vpx_dsp/loopfilter.c vpx_dsp/inv_txfm.c vpx_dsp/vpx_dsp_rtcd.c
vp9/vp9_dx_iface.c vp9/vp9_iface_common.c
vp9/common/vp9_alloccommon.c vp9/common/vp9_blockd.c vp9/common/vp9_entropy.c vp9/common/vp9_entropymode.c
vp9/common/vp9_entropymv.c vp9/common/vp9_frame_buffers.c vp9/common/vp9_idct.c vp9/common/vp9_filter.c
vp9/common/vp9_pred_common.c vp9/common/vp9_rtcd.c vp9/common/vp9_scale.c vp9/common/vp9_seg_common.c
vp9/common/vp9_tile_common.c vp9/common/vp9_loopfilter.c vp9/common/vp9_thread_common.c vp9/common/vp9_mvref_common.c
vp9/common/vp9_quant_common.c vp9/common/vp9_reconinter.c vp9/common/vp9_reconintra.c vp9/common/vp9_common_data.c
vp9/common/vp9_scan.c
vp9/decoder/vp9_decodemv.c vp9/decoder/vp9_decodeframe.c vp9/decoder/vp9_detokenize.c vp9/decoder/vp9_decoder.c
vp9/decoder/vp9_dsubexp.c vp9/decoder/vp9_job_queue.c
'''.split()
SIMD_SOURCES='''
vpx_dsp/x86/vpx_subpixel_4t_intrin_sse2.c vpx_dsp/x86/vpx_subpixel_8t_intrin_ssse3.c vpx_dsp/x86/vpx_subpixel_8t_intrin_avx2.c
vpx_dsp/x86/loopfilter_sse2.c vpx_dsp/x86/loopfilter_avx2.c
vpx_dsp/x86/inv_txfm_sse2.c vpx_dsp/x86/inv_txfm_ssse3.c vpx_dsp/x86/inv_txfm_avx2.c
vp9/common/x86/vp9_idct_intrin_sse2.c
'''.split()
RTCD=[('vp9_rtcd','vp9/common/vp9_rtcd_defs.pl'),('vpx_dsp_rtcd','vpx_dsp/vpx_dsp_rtcd_defs.pl'),('vpx_scale_rtcd','vpx_scale/vpx_scale_rtcd.pl')]

def simd_flags(rel):
    name=Path(rel).stem
    for suffix,flag in (('_avx2','-mavx2'),('_avx','-mavx'),('_sse4','-msse4.1'),('_ssse3','-mssse3')):
        if name.endswith(suffix) or suffix+'_' in name:return [flag]
    return []

def below_normal():
    if sys.platform=='win32':ctypes.windll.kernel32.SetPriorityClass(ctypes.windll.kernel32.GetCurrentProcess(),BELOW_NORMAL)

def run(cmd,**kw):
    kw.setdefault('check',True)
    if sys.platform=='win32':kw['creationflags']=BELOW_NORMAL
    return subprocess.run(cmd,**kw)

def configure_names():
    """VPX_ARCH_/HAVE_/CONFIG_ names in configure's order (ARCH_LIST, HAVE_LIST, CONFIG_LIST with their expansions)."""
    text=(SRC/'configure').read_text()
    blocks=dict(re.findall(r'^(\w+)="\n(.*?)\n"',text,re.M|re.S))
    def expand(name):
        out=[]
        for tok in blocks[name].split():
            m=re.fullmatch(r'\$\{(\w+)\}',tok)
            out+=expand(m.group(1)) if m else [tok]
        return out
    return ([('VPX_ARCH',n) for n in expand('ARCH_LIST')]+[('HAVE',n) for n in expand('HAVE_LIST')]+
            [('CONFIG',n) for n in expand('CONFIG_LIST')])

def write_config():
    CONFIG.mkdir(parents=True,exist_ok=True)
    names=[f'{p}_{n.upper()}' for p,n in configure_names()]
    h=['/* GENERATED by startup/third_party/build_vpx.py (libvpx configure equivalent: x86_64, VP9 decoder only) */',
       '#ifndef VPX_CONFIG_H','#define VPX_CONFIG_H','#define RESTRICT','#define INLINE inline']
    h+=[f'#define {n} {1 if n in ENABLED else 0}' for n in names]+['#endif /* VPX_CONFIG_H */','']
    (CONFIG/'vpx_config.h').write_text('\n'.join(h),newline='\n')
    (CONFIG/'vpx_config.txt').write_text(''.join(f'{n}={"yes" if n in ENABLED else "no"}\n' for n in names),newline='\n')
    m=re.search(r'v(\d+)\.(\d+)\.(\d+)',(SRC/'CHANGELOG').read_text().splitlines()[0])
    major,minor,patch=m.groups()
    (CONFIG/'vpx_version.h').write_text(f'''// This file is generated. Do not edit.
#ifndef VPX_VERSION_H_
#define VPX_VERSION_H_
#define VERSION_MAJOR  {major}
#define VERSION_MINOR  {minor}
#define VERSION_PATCH  {patch}
#define VERSION_EXTRA  ""
#define VERSION_PACKED ((VERSION_MAJOR<<16)|(VERSION_MINOR<<8)|(VERSION_PATCH))
#define VERSION_STRING_NOSP "v{major}.{minor}.{patch}"
#define VERSION_STRING      " v{major}.{minor}.{patch}"
#endif  // VPX_VERSION_H_
''',newline='\n')
    rt=os.environ.get('VPX_RTCD_DIR')   # builder: vendor/libvpx-rtcd (the same rtcd.pl output, shipped so no perl is needed)
    for sym,defs in RTCD:
        if rt and (Path(rt)/f'{sym}.h.raw').is_file():
            (CONFIG/f'{sym}.h.raw').write_text((Path(rt)/f'{sym}.h.raw').read_text(),newline='\n');continue
        r=run([PERL,str(SRC/'build/make/rtcd.pl'),'--arch=x86_64',f'--sym={sym}',f'--config={CONFIG/"vpx_config.txt"}',
               '--disable-mmx','--disable-avx512',str(SRC/defs)],capture_output=True,text=True)
        (CONFIG/f'{sym}.h.raw').write_text(r.stdout,newline='\n')

def coff_defined(obj):
    """External symbols defined in a COFF object."""
    data=obj.read_bytes()
    nsec,_,symptr,nsym=struct.unpack_from('<HIII',data,2)
    strtab=symptr+18*nsym;out=set();i=0
    while i<nsym:
        e=data[symptr+18*i:symptr+18*i+18]
        name=e[:8]
        if name[:4]==b'\0\0\0\0':
            off=struct.unpack_from('<I',name,4)[0];end=data.index(b'\0',strtab+off);name=data[strtab+off:end]
        else:name=name.rstrip(b'\0')
        value,secnum,typ,cls,aux=struct.unpack_from('<IhHBB',e,8)
        if secnum>0 and cls==2:out.add(name.decode())
        i+=1+aux
    return out

def filter_rtcd(defined):
    """Dispatch only to variants that exist; everything else falls back to <fn>_c."""
    dropped=0
    for sym,_ in RTCD:
        lines=(CONFIG/f'{sym}.h.raw').read_text().split('\n');out=[]
        for line in lines:
            m=re.match(r'^(\s*if \(flags & HAS_\w+\) )(\w+) = (\w+);$',line)
            if m and m.group(3) not in defined:dropped+=1;continue
            m=re.match(r'^(\s*)(\w+) = (\w+);$',line)
            if m and m.group(3) not in defined and not m.group(3).endswith('_c'):
                line=f'{m.group(1)}{m.group(2)} = {m.group(2)}_c;';dropped+=1
            m=re.match(r'^#define (\w+) (\w+)$',line)
            if m and m.group(2).startswith(m.group(1)+'_') and m.group(2) not in defined and not m.group(2).endswith('_c'):
                line=f'#define {m.group(1)} {m.group(1)}_c';dropped+=1
            out.append(line)
        (CONFIG/f'{sym}.h').write_text('\n'.join(out),newline='\n')
    return dropped

KERNEL_C='''/* GENERATED by startup/third_party/build_vpx.py: C versions of the vpx_filter_block1d* kernels that libvpx only
 * ships as nasm (vpx_subpixel_8t_*.asm, vpx_subpixel_bilinear_*.asm; not built). They are called by the compiled
 * intrinsics wrappers (FUN_CONV_1D/2D in vpx_dsp/x86/convolve.h). Same arithmetic as vpx_convolve8_c (vpx_convolve.c):
 * sum of taps, ROUND_POWER_OF_TWO(sum, 7), clip to 8 bits; avg = ROUND_POWER_OF_TWO(dst + res, 1). Pointer convention
 * of the wrappers: horizontal kernels get the unshifted source (8 taps read x-3..x+4, 2 taps x..x+1 with taps 3/4);
 * vertical kernels get src - (taps/2 - 1) rows. */
#include <stddef.h>
#include <stdint.h>
static inline uint8_t tk_clip(int v) { return (uint8_t)(v < 0 ? 0 : v > 255 ? 255 : v); }
static inline void tk_kernel(const uint8_t *s, ptrdiff_t sp, uint8_t *d, ptrdiff_t dp, uint32_t h, const int16_t *f,
                             int w, int vert, int taps, int avg) {
  int k0 = taps == 8 ? 0 : 3, k1 = taps == 8 ? 8 : 5;
  for (uint32_t y = 0; y < h; ++y, s += sp, d += dp)
    for (int x = 0; x < w; ++x) {
      int sum = 0;
      for (int k = k0; k < k1; ++k)
        sum += f[k] * (vert ? s[(ptrdiff_t)(k - (4 - taps / 2)) * sp + x] : s[x + k - 3]);
      int r = tk_clip((sum + 64) >> 7);
      d[x] = (uint8_t)(avg ? (d[x] + r + 1) >> 1 : r);
    }
}
'''
def write_kernels(defined):
    """vpx-build/config/vpx_asm_kernels.c: every sse2/ssse3 kernel name the intrinsics do not define."""
    out=[KERNEL_C];n=0
    for opt in ('sse2','ssse3'):
        for w in (4,8,16):
            for d,vert in (('h',0),('v',1)):
                for taps in (8,2):
                    for avg in ('','avg_'):
                        name=f'vpx_filter_block1d{w}_{d}{taps}_{avg}{opt}'
                        if name in defined:continue
                        out.append(f'void {name}(const uint8_t *s, ptrdiff_t sp, uint8_t *d, ptrdiff_t dp, uint32_t h, const int16_t *f) '
                                   f'{{ tk_kernel(s, sp, d, dp, h, f, {w}, {vert}, {taps}, {1 if avg else 0}); }}');n+=1
    (CONFIG/'vpx_asm_kernels.c').write_text('\n'.join(out)+'\n',newline='\n')
    return n

def compile_all(files,objdir,extra=[],base=SRC):
    objdir.mkdir(parents=True,exist_ok=True)
    def one(rel):
        obj=objdir/(rel.replace('/','_').rsplit('.',1)[0]+'.o')
        run([str(ZIG),'cc',*FLAGS,*extra,*simd_flags(rel),f'-I{CONFIG.as_posix()}',f'-I{SRC.as_posix()}','-c',str(base/rel),'-o',str(obj)])
        return obj
    with concurrent.futures.ThreadPoolExecutor(JOBS) as pool:return list(pool.map(one,files))

def main():
    key=hashlib.sha256(json.dumps([C_SOURCES,SIMD_SOURCES,FLAGS,sorted(ENABLED),KERNEL_C,JOBS>0,SHIM.read_text(),(SHIM.parent/'host_movie.h').read_text()]).encode()).hexdigest()
    lib=OUT/'libvpx.a';shim=OUT/'libtotk_movie_vpx.a';stamp=OUT/'libvpx.key'
    if lib.exists() and shim.exists() and stamp.exists() and stamp.read_text()==key:
        print(lib,file=sys.stderr);return 0
    OUT.mkdir(exist_ok=True);write_config()
    for sym,_ in RTCD:   # first pass: unfiltered headers, intrinsics only
        (CONFIG/f'{sym}.h').write_text((CONFIG/f'{sym}.h.raw').read_text(),newline='\n')
    defined=set()
    for obj in compile_all(SIMD_SOURCES,OUT/'probe'):defined|=coff_defined(obj)
    dropped=filter_rtcd(defined)
    print(f'build_vpx: {len(defined)} SIMD functions compiled; {dropped} asm-only dispatch entries fall back to C',file=sys.stderr)
    kernels=write_kernels(defined)
    print(f'build_vpx: {kernels} nasm-only convolution kernels supplied in C (vpx_asm_kernels.c)',file=sys.stderr)
    objs=compile_all(C_SOURCES+SIMD_SOURCES,OUT/'obj')+compile_all(['vpx_asm_kernels.c'],OUT/'obj',base=CONFIG)
    if lib.exists():lib.unlink()
    run([str(ZIG),'ar','rcs',str(lib),*map(str,objs)])
    sobj=OUT/'host_movie_vpx.o'
    run([str(ZIG),'cc','-target','x86_64-windows-gnu','-std=c11','-O2','-Wall','-Wextra','-Werror',f'-I{SRC.as_posix()}',
         '-c',str(SHIM),'-o',str(sobj)])
    if shim.exists():shim.unlink()
    run([str(ZIG),'ar','rcs',str(shim),str(sobj)])
    stamp.write_text(key);print(lib,file=sys.stderr);return 0

def link_args():
    """Runtime DLL link: the shim whole (referenced weakly), then libvpx. Builds them if needed."""
    if main()!=0:raise RuntimeError('libvpx build failed')
    return ['-Wl,--whole-archive',str(OUT/'libtotk_movie_vpx.a'),'-Wl,--no-whole-archive',str(OUT/'libvpx.a')]

if __name__=='__main__':below_normal();sys.exit(main())
